/**
 * webhook-receiver.js — B1: GitHub Webhooks Cloudflare Worker
 *
 * Replaces polling-based PR discovery with push-based webhook delivery,
 * achieving <1 s trigger latency for new PR events.
 *
 * Endpoint: POST /webhook/github
 *
 * SECURITY
 * - Validates the `X-Hub-Signature-256` HMAC-SHA256 header using the
 *   shared secret stored in the Worker's secret binding GITHUB_WEBHOOK_SECRET.
 * - Rejects all requests with invalid or absent signatures (401).
 * - Caps request body size to prevent memory DoS (413 if exceeded).
 * - Ignores events generated by Qodo itself to stop feedback loops.
 * - Only processes `issue_comment` events that are attached to pull requests.
 *
 * EVENT ROUTING
 * - pull_request [opened, synchronize, reopened] → enqueues a dispatch task
 *   to the Qodo pipeline via the QODO_DISPATCH_URL worker binding.
 * - push [to default branch] → enqueues a dependency-graph rebuild task.
 * - All other events → 200 OK, no-op (acknowledged but not processed).
 *
 * DESIGN INVARIANTS
 * - Worker is stateless; all state lives in Upstash Redis / R2.
 * - Never returns a 5xx to GitHub (to avoid webhook auto-disablement).
 * - Idempotent: duplicate deliveries are safe (pipeline checks run locks).
 * - Self-loop safe: events originating from the Qodo bot/app are ignored.
 */

const SUPPORTED_PR_ACTIONS = new Set(["opened", "synchronize", "reopened"]);

// Prevent memory-DoS from oversized webhook bodies (GitHub payloads are
// typically < 1 MiB; cap at 5 MiB to leave headroom for large check suites).
const MAX_BODY_BYTES = 5 * 1024 * 1024;

// Names/slugs that identify the Qodo bot/GitHub App.  Events originating from
// Qodo itself must be ignored to prevent feedback loops (e.g. Qodo posts a
// comment/check, which triggers another webhook, which triggers another run).
const DEFAULT_QODO_LOGIN = "qodo";
const DEFAULT_QODO_APP_SLUG = "qodo";

export function isQodoSender(sender, qodoLogin) {
  const login = sender?.login ?? "";
  if (!login) return false;
  const blocked = new Set([qodoLogin || DEFAULT_QODO_LOGIN, `${qodoLogin}[bot]`, "qodo[bot]"]);
  return blocked.has(login);
}

export function isQodoApp(app, qodoAppSlug) {
  const slug = app?.slug ?? "";
  const blocked = new Set([qodoAppSlug || DEFAULT_QODO_APP_SLUG, "qodo"]);
  return blocked.has(slug);
}

// ---------------------------------------------------------------------------
// HMAC-SHA256 signature verification
// ---------------------------------------------------------------------------

/**
 * Verify the GitHub `X-Hub-Signature-256` header.
 * Uses the Web Crypto API available in all CF Workers runtimes.
 *
 * @param {string}     secret   Shared webhook secret from CF binding.
 * @param {string}     rawBody  Raw request body string.
 * @param {string|null} sigHdr  Value of X-Hub-Signature-256 header.
 * @returns {Promise<boolean>}
 */
async function verifySignature(secret, rawBody, sigHdr) {
  if (!sigHdr || !sigHdr.startsWith("sha256=")) return false;

  const encoder     = new TextEncoder();
  const keyMaterial = await crypto.subtle.importKey(
    "raw",
    encoder.encode(secret),
    { name: "HMAC", hash: "SHA-256" },
    false,
    ["sign"],
  );
  const signature = await crypto.subtle.sign("HMAC", keyMaterial, encoder.encode(rawBody));
  const computed  = "sha256=" + Array.from(new Uint8Array(signature))
    .map((b) => b.toString(16).padStart(2, "0"))
    .join("");

  // Constant-time comparison to prevent timing attacks
  if (computed.length !== sigHdr.length) return false;
  let diff = 0;
  for (let i = 0; i < computed.length; i++) {
    diff |= computed.charCodeAt(i) ^ sigHdr.charCodeAt(i);
  }
  return diff === 0;
}

// ---------------------------------------------------------------------------
// Dispatch helpers
// ---------------------------------------------------------------------------

/**
 * Send a dispatch task to the Qodo pipeline worker (Option A: Qodo dispatch
 * endpoint) or push a run-context onto Upstash Redis (Option B), or trigger
 * a GitHub Actions workflow_dispatch (Option C).  The first configured option
 * is used; the rest are tried as fallbacks in order.
 *
 * @param {{ type: string; payload: unknown }} task
 * @param {object} env  CF Worker environment bindings.
 */
async function dispatchTask(task, env) {
  // Option A — dedicated Qodo dispatch worker (preferred)
  if (env.QODO_DISPATCH_URL && env.QODO_DISPATCH_SECRET) {
    const res = await fetch(env.QODO_DISPATCH_URL, {
      method: "POST",
      headers: {
        "Content-Type": "application/json",
        Authorization:  `Bearer ${env.QODO_DISPATCH_SECRET}`,
      },
      body: JSON.stringify(task),
    });
    if (res.ok) return { mode: "qodo-dispatch", ok: true };
    console.error("[webhook-receiver] qodo-dispatch failed", { status: res.status, taskType: task.type });
  }

  // Option B — Upstash Redis LPUSH onto the canonical qodo:trigger:queue
  // (ADR-003), drained by the resume-loop consumer (ADR-005). The payload is
  // shaped as a TriggerTask so the consumer's reaper can track delivery
  // attempts and staleness from first enqueue; the adapter is tolerant of the
  // legacy bare-payload shape too, so this stays backward-compatible.
  if (env.UPSTASH_REDIS_REST_URL && env.UPSTASH_REDIS_REST_TOKEN) {
    const p = task.payload || {};
    const triggerTask = {
      taskId: `trig-${Date.now().toString(36)}-${Math.random().toString(36).slice(2, 8)}`,
      owner: p.owner,
      repo: p.repo,
      prNumber: p.prNumber,
      prSha: p.prSha,
      objective: p.objective ?? p.objectiveOverride,
      trigger: p.trigger || task.type || "webhook",
      defaultBranch: p.defaultBranch,
      attempts: 0,
      enqueuedAt: Date.now(),
    };
    const res = await fetch(`${env.UPSTASH_REDIS_REST_URL}/lpush/qodo:trigger:queue`, {
      method: "POST",
      headers: {
        Authorization:   `Bearer ${env.UPSTASH_REDIS_REST_TOKEN}`,
        "Content-Type":  "application/json",
      },
      body: JSON.stringify([JSON.stringify(triggerTask)]),
    });
    if (res.ok) return { mode: "redis-queue", ok: true };
    console.error("[webhook-receiver] redis-queue dispatch failed", { status: res.status });
  }

  // Option C — GitHub Actions workflow_dispatch (fully event-driven, no polling)
  if (env.GITHUB_TOKEN && env.GITHUB_DISPATCH_WORKFLOW && task.payload?.owner && task.payload?.repo) {
    const { owner, repo, prNumber, trigger } = task.payload;
    const defaultBranch = task.payload?.defaultBranch || "main";
    const res = await fetch(
      `https://api.github.com/repos/${owner}/${repo}/actions/workflows/${env.GITHUB_DISPATCH_WORKFLOW}/dispatches`,
      {
        method: "POST",
        headers: {
          Authorization:  `Bearer ${env.GITHUB_TOKEN}`,
          Accept:         "application/vnd.github+json",
          "Content-Type": "application/json",
        },
        body: JSON.stringify({
          ref:    defaultBranch,
          inputs: { pr_number: String(prNumber ?? ""), trigger: trigger ?? "webhook" },
        }),
      },
    );
    if (res.ok) return { mode: "actions-dispatch", ok: true };
    console.error("[webhook-receiver] actions-dispatch failed", { status: res.status });
  }

  console.error("[webhook-receiver] all dispatch methods failed for task", { taskType: task.type });
  return { mode: "none", ok: false };
}

// ---------------------------------------------------------------------------
// Event handlers
// ---------------------------------------------------------------------------

/**
 * Handle a pull_request event.
 *
 * @param {object} payload  Parsed GitHub webhook payload.
 * @param {object} env      CF Worker environment bindings.
 */
async function handlePullRequest(payload, env) {
  const { action, pull_request: pr, repository: repo } = payload;
  if (!SUPPORTED_PR_ACTIONS.has(action)) return;

  const owner          = repo?.owner?.login      ?? "";
  const repoName       = repo?.name               ?? "";
  const defaultBranch  = repo?.default_branch     ?? "main";
  const prNumber       = pr?.number               ?? 0;
  const prSha          = pr?.head?.sha            ?? "";
  const objective      = pr?.title                ?? "";

  if (!owner || !repoName || !prNumber) {
    console.warn("[webhook-receiver] pull_request payload missing required fields");
    return;
  }

  console.log("[webhook-receiver] PR event", { action, owner, repo: repoName, pr: prNumber });

  await dispatchTask(
    {
      type: "pipeline_trigger",
      payload: { owner, repo: repoName, prNumber, prSha, objective, defaultBranch, trigger: "webhook:pull_request" },
    },
    env,
  );
}

/**
 * Handle a push event (default branch only) → trigger dep-graph rebuild.
 *
 * @param {object} payload  Parsed GitHub webhook payload.
 * @param {object} env      CF Worker environment bindings.
 */
async function handlePush(payload, env) {
  const { ref, repository: repo } = payload;
  const defaultBranch = `refs/heads/${repo?.default_branch ?? "main"}`;
  if (ref !== defaultBranch) return;

  const owner    = repo?.owner?.login ?? "";
  const repoName = repo?.name         ?? "";
  if (!owner || !repoName) return;

  console.log("[webhook-receiver] push to default branch", { owner, repo: repoName });

  await dispatchTask(
    {
      type: "dep_graph_rebuild",
      payload: { owner, repo: repoName },
    },
    env,
  );
}

/**
 * Handle an issue_comment event — route "@qodo ..." commands to the pipeline.
 * Recognises "/qodo proceed" (resume a paused preflight confirmation) and
 * general "@qodo <instruction>" style invocations.
 *
 * @param {object} payload  Parsed GitHub webhook payload.
 * @param {object} env      CF Worker environment bindings.
 */
async function handleIssueComment(payload, env) {
  if (payload.action !== "created") return;

  const body     = payload?.comment?.body ?? "";
  const repo     = payload?.repository;
  const owner    = repo?.owner?.login ?? "";
  const repoName = repo?.name         ?? "";
  const prNumber = payload?.issue?.number ?? 0;

  // Ignore comments from the Qodo bot to prevent feedback loops.
  if (isQodoSender(payload?.sender, env.QODO_BOT_LOGIN)) {
    console.log("[webhook-receiver] ignoring comment from Qodo sender");
    return;
  }

  // Ignore comments on regular issues; only act on pull requests.
  if (!payload?.issue?.pull_request) return;

  if (!owner || !repoName || !prNumber) return;

  // "/qodo proceed" — resume a pipeline paused for preflight confirmation
  if (/^\/qodo\s+proceed\b/i.test(body.trim())) {
    console.log("[webhook-receiver] issue_comment: /qodo proceed", { owner, repo: repoName, prNumber });
    await dispatchTask(
      {
        type: "pipeline_resume",
        payload: { owner, repo: repoName, prNumber, trigger: "webhook:issue_comment:proceed" },
      },
      env,
    );
    return;
  }

  // "/qodo cancel" — cancel a paused run
  if (/^\/qodo\s+cancel\b/i.test(body.trim())) {
    console.log("[webhook-receiver] issue_comment: /qodo cancel", { owner, repo: repoName, prNumber });
    await dispatchTask(
      {
        type: "pipeline_cancel",
        payload: { owner, repo: repoName, prNumber, trigger: "webhook:issue_comment:cancel" },
      },
      env,
    );
    return;
  }

  // "@qodo <instruction>" — ad-hoc objective override
  if (/@qodo\b/i.test(body)) {
    const objectiveOverride = body.replace(/@qodo\b/i, "").trim();
    const defaultBranch = payload?.repository?.default_branch ?? "main";
    console.log("[webhook-receiver] issue_comment: @qodo mention", { owner, repo: repoName, prNumber });
    await dispatchTask(
      {
        type: "pipeline_trigger",
        payload: {
          owner, repo: repoName, prNumber,
          objectiveOverride, defaultBranch,
          trigger: "webhook:issue_comment",
        },
      },
      env,
    );
  }
}

/**
 * Handle a check_suite completed-with-failure event → re-trigger analysis.
 *
 * @param {object} payload  Parsed GitHub webhook payload.
 * @param {object} env      CF Worker environment bindings.
 */
async function handleCheckSuite(payload, env) {
  if (payload.action !== "completed") return;
  if (payload.check_suite?.conclusion !== "failure") return;

  // Ignore check suites created by Qodo itself to prevent feedback loops.
  if (isQodoApp(payload?.check_suite?.app, env.QODO_APP_SLUG)) {
    console.log("[webhook-receiver] ignoring check_suite from Qodo app");
    return;
  }

  const repo          = payload?.repository;
  const owner         = repo?.owner?.login  ?? "";
  const repoName      = repo?.name            ?? "";
  const defaultBranch = repo?.default_branch  ?? "main";
  const headSha       = payload.check_suite?.head_sha ?? "";

  // Resolve PR number from check suite if available
  const prNumber = payload.check_suite?.pull_requests?.[0]?.number ?? null;

  if (!owner || !repoName) return;

  console.log("[webhook-receiver] check_suite failure", { owner, repo: repoName, headSha, prNumber });

  await dispatchTask(
    {
      type: "pipeline_trigger",
      payload: {
        owner, repo: repoName, prNumber, headSha, defaultBranch,
        trigger: "webhook:check_suite_failure",
      },
    },
    env,
  );
}

// ---------------------------------------------------------------------------
// Main fetch handler
// ---------------------------------------------------------------------------

export default {
  /**
   * @param {Request} request
   * @param {object}  env      CF Worker env bindings:
   *                             - GITHUB_WEBHOOK_SECRET (string, required)
   *                             - QODO_DISPATCH_URL     (string, optional)
   *                             - QODO_DISPATCH_SECRET  (string, optional)
   *                             - UPSTASH_REDIS_REST_URL   (string, optional)
   *                             - UPSTASH_REDIS_REST_TOKEN (string, optional)
   *                             - GITHUB_TOKEN              (string, optional)
   *                             - GITHUB_DISPATCH_WORKFLOW  (string, optional)
   *                             - QODO_BOT_LOGIN            (string, optional, default "qodo")
   *                             - QODO_APP_SLUG             (string, optional, default "qodo")
   */
  async fetch(request, env) {
    if (request.method !== "POST") {
      return new Response("Method Not Allowed", { status: 405 });
    }

    const url = new URL(request.url);
    if (url.pathname !== "/webhook/github") {
      return new Response("Not Found", { status: 404 });
    }

    // ── Read and verify body ──────────────────────────────────────────────
    const contentLength = Number(request.headers.get("Content-Length") || "0");
    if (contentLength > MAX_BODY_BYTES) {
      console.warn("[webhook-receiver] body too large", { contentLength, max: MAX_BODY_BYTES });
      return new Response("Payload Too Large", { status: 413 });
    }

    const rawBody = await request.text();
    if (rawBody.length > MAX_BODY_BYTES) {
      console.warn("[webhook-receiver] body exceeds max size", { size: rawBody.length, max: MAX_BODY_BYTES });
      return new Response("Payload Too Large", { status: 413 });
    }

    const sigHdr  = request.headers.get("X-Hub-Signature-256");
    const secret  = env.GITHUB_WEBHOOK_SECRET ?? "";

    if (!secret) {
      console.error("[webhook-receiver] GITHUB_WEBHOOK_SECRET binding is missing");
      return new Response("Internal Configuration Error", { status: 500 });
    }

    const valid = await verifySignature(secret, rawBody, sigHdr);
    if (!valid) {
      console.warn("[webhook-receiver] invalid signature", { sig: sigHdr?.slice(0, 20) });
      return new Response("Unauthorized", { status: 401 });
    }

    // ── Parse payload ─────────────────────────────────────────────────────
    let payload;
    try {
      payload = JSON.parse(rawBody);
    } catch {
      return new Response("Bad Request", { status: 400 });
    }

    const event = request.headers.get("X-GitHub-Event") ?? "";

    // ── Route event ───────────────────────────────────────────────────────
    try {
      if (event === "pull_request") {
        await handlePullRequest(payload, env);
      } else if (event === "push") {
        await handlePush(payload, env);
      } else if (event === "issue_comment") {
        await handleIssueComment(payload, env);
      } else if (event === "check_suite") {
        await handleCheckSuite(payload, env);
      } else {
        // Acknowledge but do nothing
        console.log("[webhook-receiver] unhandled event type", { event });
      }
    } catch (err) {
      // Log but never 5xx — GitHub would disable the webhook after repeated failures.
      console.error("[webhook-receiver] handler error", { event, error: String(err) });
    }

    return new Response(JSON.stringify({ ok: true }), {
      status: 200,
      headers: { "Content-Type": "application/json" },
    });
  },
};
